python3 -c "
import json
for f in ['artifacts/plan011_new_cms.json', 'artifacts/plan011_new_cms_round2.json', 'artifacts/plan011_new_cms_vast_qwen3_zs.json', 'artifacts/plan011_frontier_cms.json']:
    try:
        data = json.load(open(f))
        vast_keys = [k for k in data.keys() if 'vast' in k.lower()]
        if not vast_keys:
            # check nested
            for top_k, v in data.items():
                if isinstance(v, dict):
                    vk = [kk for kk in v.keys() if 'vast' in kk.lower()]
                    if vk:
                        vast_keys.extend(vk)
                        print(f'{f} -> {top_k}: {vk}')
        else:
            print(f'{f}: {vast_keys}')
        if not vast_keys:
            print(f'{f}: no vast keys. Top keys: {list(data.keys())[:5]}')
    except Exception as e:
        print(f'{f}: ERROR {e}')
"

