    vast = [x for x in per if 'vast' in str(x.get('config', x.get('name', ''))).lower()]
    for v in vast:
        print(v.get('config', v.get('name', 'unknown')), v.get('d_rel'))
elif isinstance(per, dict):
    vast = {k:v for k,v in per.items() if 'vast' in k.lower()}
    for k,v in vast.items():
        print(k, v.get('d_rel'))
